function makeLine(points, color = black, linewidth = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const mat = new THREE.LineBasicMaterial({ color, linewidth });
  const line = new THREE.Line(geom, mat);
  scene.add(line);
  return line;
}

function makePolyline(points, color = black) {
  return makeLine(points.map(p => new THREE.Vector3(p[0], p[1], p[2] ?? 0.02)), color);
}

function makeArrow(start, end, color = black, headLength = 0.22, headWidth = 0.15) {
  const s = start.clone();
  const e = end.clone();
  const dir = e.clone().sub(s);
  const len = dir.length();
  const arrow = new THREE.ArrowHelper(dir.normalize(), s, len, color, headLength, headWidth);
  arrow.cone.material.color.setHex(color);
  arrow.line.material.color.setHex(color);
  scene.add(arrow);
  return arrow;
}

function makeCuboid(name, cx, bottom, w, h, dep, opts = {}) {
