}

function createSyntheticFaceTexture() {
  const W = 48, H = 64;
  const data = new Uint8Array(W * H * 3);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = (y * W + x) * 3;
      const nx = (x / (W - 1)) * 2 - 1;
      const ny = (y / (H - 1)) * 2 - 1;
      let r = 185 + 28 * Math.sin(8 * nx + 2 * ny);
      let g = 190 + 22 * Math.cos(6 * ny);
      let b = 190 + 25 * Math.sin(5 * nx - 3 * ny);
      const face = (nx * nx / 0.52 + (ny + 0.05) * (ny + 0.05) / 0.78) < 1;
      if (face) {
        r = 210 + 25 * Math.sin(12 * nx);
        g = 205 + 18 * Math.cos(8 * ny);
        b = 190 + 10 * Math.sin(6 * nx * ny);
      }
      const eyeL = ((nx + 0.28) ** 2 / 0.018 + (ny + 0.1) ** 2 / 0.01) < 1;
      const eyeR = ((nx - 0.25) ** 2 / 0.018 + (ny + 0.1) ** 2 / 0.01) < 1;
      const mouth = ((nx + 0.02) ** 2 / 0.17 + (ny - 0.45) ** 2 / 0.012) < 1;
      const hair = ny < -0.46 + 0.13 * Math.sin(8 * nx);
      const brightPatch = ((nx - 0.62) ** 2 / 0.07 + (ny - 0.32) ** 2 / 0.05) < 1;
      if (hair) { r = 55; g = 70; b = 78; }
      if (eyeL || eyeR || mouth) { r = 30; g = 40; b = 48; }
      if (brightPatch) { r = 240; g = 170; b = 25; }
      const qx = Math.floor(x / 3), qy = Math.floor(y / 3);
      const noise = ((qx * 37 + qy * 73) % 29) - 14;
      data[i] = THREE.MathUtils.clamp(r + noise, 0, 255);
      data[i + 1] = THREE.MathUtils.clamp(g + noise, 0, 255);
      data[i + 2] = THREE.MathUtils.clamp(b + noise, 0, 255);
    }
  }
  const tex = new THREE.DataTexture(data, W, H, THREE.RGBFormat);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestFilter;
  tex.needsUpdate = true;
  return tex;
}

function makeImagePlane() {
  const cx = -1.05, bottom = 0.95, w = 1.25, h = 2.75, dep = 0.08;
  const group = new THREE.Group();
  group.name = '64 × 64 × 3 image';

  const tex = createSyntheticFaceTexture();
  const plane = new THREE.Mesh(
