  const x0 = cx - w / 2, x1 = cx + w / 2, y0 = bottom, y1 = bottom + h, zf = 0, zb = -dep;
  const sideGeom = new THREE.BufferGeometry();
  sideGeom.setAttribute('position', new THREE.Float32BufferAttribute([
