    [x0,y0,zf],[x1,y0,zf],[x1,y1,zf],[x0,y1,zf],[x0,y0,zf],
    [x1,y0,zb],[x1,y1,zb],[x0,y1,zb],
    [x1,y1,zf],[x1,y1,zb],
    [x1,y0,zf],[x1,y0,zb],
