  ], black);
}

function makeTopBrace(x0, x1, y) {
  const pts = [];
  const z = 0.02;
  const mid = (x0 + x1) / 2;
  const hook = 0.32;
  const dip = 0.13;
  for (let i = 0; i <= 14; i++) {
    const t = i / 14;
    pts.push(new THREE.Vector3(x0 + hook * t, y - dip * Math.sin((1 - t) * Math.PI / 2), z));
  }
  pts.push(new THREE.Vector3(mid - 0.18, y, z));
  pts.push(new THREE.Vector3(mid - 0.06, y - 0.08, z));
  pts.push(new THREE.Vector3(mid, y - 0.12, z));
  pts.push(new THREE.Vector3(mid + 0.06, y - 0.08, z));
  pts.push(new THREE.Vector3(mid + 0.18, y, z));
  pts.push(new THREE.Vector3(x1 - hook, y, z));
  for (let i = 0; i <= 14; i++) {
    const t = i / 14;
    pts.push(new THREE.Vector3(x1 - hook + hook * t, y - dip * Math.sin(t * Math.PI / 2), z));
  }
  return makeLine(pts, black);
}

