      ? 0.5 + Math.atan(s) / Math.PI
      : 1 / (1 + Math.exp(-s));
    pts.push(new THREE.Vector3(
      insetOrigin.x + ((s + 6) / 12) * insetW,
      insetOrigin.y + v * insetH,
      insetOrigin.z
    ));
  }
  curveLine.geometry.dispose();
  curveLine.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  curveMat.color.setHex(mode === 'Arctan' ? 0x2aa7a7 : 0x7d2dd2);
}

