function createFaceTexture() {
  const W = 56;
  const H = 64;
  const data = new Uint8Array(W * H * 3);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = (y * W + x) * 3;
      const nx = (x / (W - 1)) * 2 - 1;
      const ny = (y / (H - 1)) * 2 - 1;
      let r = 178 + 18 * Math.sin(7 * nx + 3 * ny);
      let g = 184 + 20 * Math.cos(6 * ny - nx);
      let b = 184 + 25 * Math.sin(4 * nx - 4 * ny);
      const face = (nx * nx / 0.55 + (ny + 0.02) * (ny + 0.02) / 0.78) < 1;
      if (face) {
        r = 211 + 21 * Math.sin(10 * nx);
        g = 204 + 17 * Math.cos(7 * ny);
        b = 188 + 12 * Math.sin(5 * nx * ny);
      }
      const hair = ny < -0.48 + 0.12 * Math.sin(9 * nx) && Math.abs(nx) < 0.86;
      const eyeL = ((nx + 0.28) * (nx + 0.28) / 0.018 + (ny + 0.07) * (ny + 0.07) / 0.012) < 1;
      const eyeR = ((nx - 0.26) * (nx - 0.26) / 0.018 + (ny + 0.07) * (ny + 0.07) / 0.012) < 1;
      const mouth = ((nx + 0.02) * (nx + 0.02) / 0.18 + (ny - 0.43) * (ny - 0.43) / 0.018) < 1;
      const bright = ((nx - 0.66) * (nx - 0.66) / 0.055 + (ny - 0.34) * (ny - 0.34) / 0.055) < 1;
      const shadow = ((nx + 0.62) * (nx + 0.62) / 0.06 + (ny - 0.1) * (ny - 0.1) / 0.18) < 1;
      if (hair) { r = 53; g = 66; b = 73; }
      if (eyeL || eyeR || mouth) { r = 26; g = 35; b = 40; }
      if (bright) { r = 238; g = 171; b = 31; }
      if (shadow) { r *= 0.63; g *= 0.68; b *= 0.74; }
      const qx = Math.floor(x / 3);
      const qy = Math.floor(y / 3);
      const noise = ((qx * 41 + qy * 67) % 31) - 15;
      data[i] = THREE.MathUtils.clamp(Math.round(r + noise), 0, 255);
      data[i + 1] = THREE.MathUtils.clamp(Math.round(g + noise), 0, 255);
      data[i + 2] = THREE.MathUtils.clamp(Math.round(b + noise), 0, 255);
    }
  }
  const tex = new THREE.DataTexture(data, W, H, THREE.RGBFormat);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestFilter;
  tex.needsUpdate = true;
  return tex;
}

