function setActiveObject(obj) {
  for (const [target, helper] of helpers) {
    helper.visible = target === obj;
    if (helper.visible) helper.update();
  }
}

function setGlowSegment(fromObj, toObj, t) {
  const p0 = centers.get(fromObj).clone();
  const p1 = centers.get(toObj).clone();
  const pEnd = p0.clone().lerp(p1, THREE.MathUtils.clamp(t, 0, 1));
  const arr = glowSegment.geometry.attributes.position.array;
  arr[0] = p0.x; arr[1] = p0.y; arr[2] = p0.z + 0.18;
  arr[3] = pEnd.x; arr[4] = pEnd.y; arr[5] = pEnd.z + 0.18;
  glowSegment.geometry.attributes.position.needsUpdate = true;
  glowSegment.visible = true;
}

function stopSequence() {
  if (activeAnimation) cancelAnimationFrame(activeAnimation);
  activeAnimation = null;
  setActiveObject(null);
  glowSegment.visible = false;
}

function playSequence(sequence, secondsPerHop = 0.72) {
  stopSequence();
  const start = performance.now();
  const totalHops = sequence.length - 1;

  function frame(now) {
    const elapsed = (now - start) / 1000;
    const hopFloat = elapsed / secondsPerHop;
    const hop = Math.min(Math.floor(hopFloat), totalHops);
    const frac = Math.min(1, hopFloat - hop);
    const current = sequence[Math.min(hop, sequence.length - 1)];
    setActiveObject(current);
    if (hop < totalHops) {
      setGlowSegment(sequence[hop], sequence[hop + 1], frac);
    } else {
      glowSegment.visible = false;
    }

    if (elapsed < totalHops * secondsPerHop + 0.65) {
      activeAnimation = requestAnimationFrame(frame);
    } else {
      stopSequence();
    }
  }

  activeAnimation = requestAnimationFrame(frame);
}

function playGenerator() {
  playSequence([latent, g4, g8, g16, g32, image], 0.72);
}

function playDiscriminator() {
  playSequence([image, d32, d16, d8, d4, scalarGroup], 0.72);
}

function pulseScalar() {
  if (pulseRAF) cancelAnimationFrame(pulseRAF);
  const start = performance.now();
  const duration = 900;
  setActiveObject(scalarGroup);

  function frame(now) {
    const t = Math.min(1, (now - start) / duration);
    const pulse = Math.sin(t * Math.PI);
    const s = 1 + 0.45 * pulse;
    scalarA.scale.setScalar(s);
    scalarB.scale.setScalar(s);
    scalarA.material.color.setHex(pulse > 0.2 ? 0xffee66 : COLOR_TEAL);
    scalarB.material.color.setHex(pulse > 0.2 ? 0xffee66 : COLOR_TEAL);

    if (t < 1) {
      pulseRAF = requestAnimationFrame(frame);
    } else {
      scalarA.scale.setScalar(1);
      scalarB.scale.setScalar(1);
      scalarA.material.color.setHex(COLOR_TEAL);
      scalarB.material.color.setHex(COLOR_TEAL);
      setActiveObject(null);
      pulseRAF = null;
    }
  }

  pulseRAF = requestAnimationFrame(frame);
}

function setFinalActivation(mode) {
  const clean = mode === 'Arctan' ? 'Arctan' : 'Sigmoid';
  const select = document.getElementById('finalActivation');
  if (select) select.value = clean;
  activationLabel.div.innerHTML = clean === 'Arctan' ? 'arctan' : 'sigmoid';
  probabilityLabel.div.innerHTML = clean === 'Arctan'
    ? '<i>Pr</i> (real)<br><span style="font-size:13px">scaled arctan</span>'
    : '<i>Pr</i> (real)';
  updateActivationCurve(clean);
  pulseScalar();
}

document.getElementById('generatorForwardPass').addEventListener('click', playGenerator);
document.getElementById('discriminatorForwardPass').addEventListener('click', playDiscriminator);
document.getElementById('finalActivation').addEventListener('change', e => setFinalActivation(e.target.value));

const demoSteps = [
  {
    title: 'Generator expands noise into an image',
    narration: 'Play the generator animation. The highlight travels from the 100 × 1 latent vector through 4 × 4 × 1024, 8 × 8 × 512, 16 × 16 × 256, and 32 × 32 × 128, ending at the 64 × 64 × 3 image plane.',
    state: { finalActivation: 'Sigmoid' },
    action: playGenerator
  },
  {
    title: 'Discriminator compresses an image into a score',
    narration: 'Play the discriminator animation. The highlight begins at the image input x or x* and moves through strided convolution blocks until the 4 × 4 convolution collapses the representation to a 1 × 1 real/fake output.',
    state: { finalActivation: 'Sigmoid' },
    action: playDiscriminator
  },
  {
    title: 'Compare final activation choices',
    narration: 'Switch the final activation from sigmoid to arctan. The output block and curve inset update to show how the same scalar can be mapped with a different saturating nonlinearity.',
    state: { finalActivation: 'Arctan' },
    action: pulseScalar
  }
];

let currentStep = 0;

function goToStep(i) {
  currentStep = (i + demoSteps.length) % demoSteps.length;
  const step = demoSteps[currentStep];
  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('stepNarration').textContent = step.narration;
  setFinalActivation(step.state.finalActivation);
  if (typeof step.action === 'function') {
    setTimeout(step.action, 120);
  }
}

window.goToStep = goToStep;

document.getElementById('stepPrev').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(currentStep + 1));

goToStep(0);
